<template><div><div class="grid gap-4 md:grid-cols-4 mb-6"><el-card v-for="s in stats" :key="s.label"><p class="text-xs text-gray-400 uppercase">{{ s.label }}</p><p class="text-3xl font-black mt-2" :class="s.color">{{ s.value }}</p></el-card></div><el-card><div class="flex items-center justify-between mb-4"><span class="font-bold">Risk Ranking</span><el-button size="small" type="warning" @click="retrain">Retrain</el-button></div><el-table :data="predictions" stripe><el-table-column prop="full_name" label="Name" /><el-table-column prop="department_name" label="Dept" /><el-table-column label="Risk"><template #default="{row}"><el-tag :type="row.risk_score>80?'danger':row.risk_score>50?'warning':'success'">{{ row.risk_score }}%</el-tag></template></el-table-column><el-table-column prop="tenure" label="Tenure" /><el-table-column prop="engagement_score" label="Engagement" /></el-table></el-card></div></template><script setup lang="ts">import {ref,onMounted}from 'vue';import {ElMessage}from 'element-plus';import {getPredictions,trainModel}from '@/api/hrms';const emit=defineEmits(['update-title']);emit('update-title','Attrition Warning');const predictions=ref<any[]>([]);const stats=ref([{label:'Total',value:0,color:'text-gray-900'},{label:'High Risk',value:0,color:'text-red-600'},{label:'Medium',value:0,color:'text-yellow-600'},{label:'Low',value:0,color:'text-green-600'}]);async function load(){try{const r:any=await getPredictions();predictions.value=r.data||[];const t=predictions.value.length;const h=predictions.value.filter((p:any)=>p.risk_score>80).length;const m=predictions.value.filter((p:any)=>p.risk_score>50&&p.risk_score<=80).length;stats.value=[{label:'Total',value:t,color:'text-gray-900'},{label:'High Risk',value:h,color:'text-red-600'},{label:'Medium',value:m,color:'text-yellow-600'},{label:'Low',value:t-h-m,color:'text-green-600'}]}catch(e){}}async function retrain(){try{await trainModel();ElMessage.success('Done');load()}catch(e:any){ElMessage.error(e.message)}}onMounted(load)</script>
